steps.code:
# Get Splitwise expenses created yesterday
splitwise_token = splitwise_login['access_token']
yesterday_str = yesterday.isoformat()
expenses = []
page = 0
while True:
    resp = apis.splitwise.show_activity(access_token=splitwise_token, show_expenses=True, show_payments=False, page_index=page, page_limit=20, sort_by='-created_at')
    if isinstance(resp, dict) and 'message' in resp:
        print("Error:", resp)
        break
    if not resp:
        break
    # Filter records that are expenses and created yesterday
    for rec in resp:
        if rec.get('record_type') == 'expense' and rec.get('created_at', '').startswith(yesterday_str):
            expenses.append(rec)
    if len(resp) < 20:
        break
    page += 1
print("Splitwise expenses created yesterday:", len(expenses))
for e in expenses:
    print(e)

