# Let's get all groups by paginating through all pages
all_groups = []
for page in range(0, 10):
    resp = apis.splitwise.show_groups(access_token=splitwise_token, page_index=page, page_limit=5)
    if not resp:
        break
    all_groups.extend(resp)
    if len(resp) < 5:
        break
print(f"Total groups: {len(all_groups)}")
for g in all_groups:
    print(g['group_id'], g['name'])

